import{_ as e}from"./plugin-vue_export-helper-c27b6911.js";import{o as t,c as o,d as r}from"./app-76860c1c.js";const a={},i=r('<h1 id="migrate-game-files-after-editor-update" tabindex="-1"><a class="header-anchor" href="#migrate-game-files-after-editor-update" aria-hidden="true">#</a> Migrate Game Files After Editor Update</h1><p>WebGAL Terre 4.6 significantly changes how user data is organized. This page keeps the migration notes for version 4.5 and earlier, and adds the required migration path from 4.5 to 4.6.</p><h2 id="upgrading-from-4-5-to-4-6" tabindex="-1"><a class="header-anchor" href="#upgrading-from-4-5-to-4-6" aria-hidden="true">#</a> Upgrading from 4.5 to 4.6</h2><p>Starting from 4.6, WebGAL Terre stores games, templates, custom engines, and exported files in a unified user data directory. The 4.6 installation directory no longer provides the old user project directories such as <code>public/games</code>, <code>public/templates</code>, and <code>assets/templates/Derivative_Engine</code> by default, so copying 4.5 files into the same paths under the 4.6 installation directory is no longer a valid migration method.</p><p>Migrate manually as follows:</p><ol><li>Open WebGAL Terre 4.6 once so Terre can create the new user data directory.</li><li>In WebGAL Terre 4.6, open Settings, go to the user data settings, and click the button to open the user data directory.</li><li>Open the installation directory of your old WebGAL Terre 4.5.</li><li>Copy each game project folder from <code>public/games</code> in 4.5 to the <code>games</code> directory in the 4.6 user data directory.</li><li>If you have custom templates, copy the custom template folders from <code>public/templates</code> in 4.5 to the <code>templates</code> directory in the 4.6 user data directory. Built-in templates do not need to be copied.</li><li>If you imported custom engines, copy the custom engine folders from <code>assets/templates/Derivative_Engine</code> in 4.5 to the <code>derivative-engines</code> directory in the 4.6 user data directory.</li><li>Return to WebGAL Terre 4.6, refresh the game list and template list or restart Terre, then confirm that the content appears.</li></ol><p>The main directories in the 4.6 user data directory are:</p><ul><li><code>games</code>: stores your game projects. Old <code>public/games/&lt;game name&gt;</code> folders should become <code>games/&lt;game name&gt;</code>.</li><li><code>templates</code>: stores custom templates you created or imported. Old <code>public/templates/&lt;template name&gt;</code> folders should become <code>templates/&lt;template name&gt;</code>.</li><li><code>derivative-engines</code>: stores custom engines. Old <code>assets/templates/Derivative_Engine/&lt;engine name&gt;</code> folders should become <code>derivative-engines/&lt;engine name&gt;</code>.</li><li><code>Exported_Games</code>: stores games exported from Terre.</li><li><code>config.json</code>: stores Terre user data configuration. Do not edit it manually unless you understand the fields.</li></ul><p>If you use portable mode, the actual user data directory is the <code>data</code> folder inside the installation directory. The migration target is still the <code>games</code>, <code>templates</code>, and <code>derivative-engines</code> directories under that folder.</p><p>Starting from 4.6, future WebGAL Terre upgrades no longer require manual game file migration. The user data directory will continue to be reused after upgrading, unless you manually change the user data directory or switch data locations in portable mode.</p><h2 id="migrating-games-between-4-5-and-earlier-versions" tabindex="-1"><a class="header-anchor" href="#migrating-games-between-4-5-and-earlier-versions" aria-hidden="true">#</a> Migrating Games Between 4.5 and Earlier Versions</h2><p>The following notes only apply to migration between 4.5 and earlier versions. If you are upgrading to 4.6 or later, use the user data directory migration method above.</p><p>WebGAL Terre editor&#39;s game project files are located in the <code>public/games</code> directory. In this directory, you can see the names of the games you have created.</p><p>After you download or install the new editor, you can directly migrate the games from the old editor to the same directory of the new editor, and then open the new editor to use them.</p><p>Except for major version upgrades (the first digit of the version number), compatibility is not guaranteed, but in general, games are backward compatible.</p><h2 id="migrating-templates-and-custom-engines-between-4-5-and-earlier-versions" tabindex="-1"><a class="header-anchor" href="#migrating-templates-and-custom-engines-between-4-5-and-earlier-versions" aria-hidden="true">#</a> Migrating Templates and Custom Engines Between 4.5 and Earlier Versions</h2><p>If you have created templates or imported custom engines, you will also need to migrate these files to the new version of the editor. Template files are located in the <code>public/templates</code> directory.<br> Custom engines are located in the <code>assets/templates/Derivative_Engine</code> directory. You will need to migrate these files to the same directory in the new version.</p>',17),d=[i];function n(s,l){return t(),o("div",null,d)}const g=e(a,[["render",n],["__file","migration.html.vue"]]);export{g as default};
